// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(address depositor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        vm.deal(depositor, depositAmount);
        vm.startPrank(depositor);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = address(c).balance;
        vm.stopPrank();
        balanceBefore = address(c).balance;
        vm.prank(depositor);
        try c.withdrawAll() { } catch { }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter < balanceBefore);
    }
}
